void v5i(){for(int i=0;i<4;i++){pvx[i]=pvy[i]=pda[i]=0;pcol[i]=false;}for(int i=0;i<4;i++){rvt[i]=rvc[i]=rti[i]=rdv[i]=0;}}
void v5u(){
for(int i=0;i<4;i++)pcol[i]=false;
double d02=sqrt((P[0].x-P[2].x)*(P[0].x-P[2].x)+(P[0].y-P[2].y)*(P[0].y-P[2].y)+1e-8);
double d03=sqrt((P[0].x-P[3].x)*(P[0].x-P[3].x)+(P[0].y-P[3].y)*(P[0].y-P[3].y)+1e-8);
double d12=sqrt((P[1].x-P[2].x)*(P[1].x-P[2].x)+(P[1].y-P[2].y)*(P[1].y-P[2].y)+1e-8);
double d13=sqrt((P[1].x-P[3].x)*(P[1].x-P[3].x)+(P[1].y-P[3].y)*(P[1].y-P[3].y)+1e-8);
pcol[0]=(d02<801)||(d03<801);pcol[1]=(d12<801)||(d13<801);
pcol[2]=(d02<801)||(d12<801);pcol[3]=(d03<801)||(d13<801);
double t0cx=(P[0].x+P[1].x)*0.5,t0cy=(P[0].y+P[1].y)*0.5;
double t1cx=(P[2].x+P[3].x)*0.5,t1cy=(P[2].y+P[3].y)*0.5;
int opps[4]={2,3,0,1};double tcx[4]={t0cx,t0cx,t1cx,t1cx};double tcy[4]={t0cy,t0cy,t1cy,t1cy};
for(int k=0;k<4;k++){int oa=opps[k];
double dtx=tcx[k]-P[oa].x,dty=tcy[k]-P[oa].y;
double dtd=sqrt(dtx*dtx+dty*dty+1e-8);
float ivt=(P[oa].vx*dtx+P[oa].vy*dty)/dtd;
int cg=min(gc[oa],ng-1);
double cpx=gx[cg]-P[oa].x,cpy=gy[cg]-P[oa].y;
double cpd=sqrt(cpx*cpx+cpy*cpy+1e-8);
float ivc=(P[oa].vx*cpx+P[oa].vy*cpy)/cpd;
double spd=sqrt(P[oa].vx*P[oa].vx+P[oa].vy*P[oa].vy+1e-8);
float idv=ivc/spd;
rvt[k]=0.1f*ivt+0.9f*rvt[k];
rvc[k]=0.1f*ivc+0.9f*rvc[k];
rdv[k]=0.1f*idv+0.9f*rdv[k];}
}
double rtti(double*px,double*py,double*vx,double*vy,int i,int j){
double rpx=px[j]-px[i],rpy=py[j]-py[i],rvx=vx[j]-vx[i],rvy=vy[j]-vy[i];
double p2=rpx*rpx+rpy*rpy,v2=rvx*rvx+rvy*rvy,dot=rpx*rvx+rpy*rvy;
double c2=p2-640000.0,disc=dot*dot-v2*c2;
double ds=max(disc,0.0),sq=sqrt(ds),dn=-dot+sq;
double dns=(dn<=1e-6)?1.0:dn,tc=c2/dns;
bool nh=(dot>=0.0)||(disc<0.0)||(v2<1e-6),ol=c2<=0.0;
double t=ol?0.0:(nh?10.0:min(tc,10.0));return t/10.0;}
